#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);              /* 1. Leer cuántos datos vienen */
    double x, suma = 0.0;
    for (int i = 0; i < n; i++) {  /* 2. Acumular cada calificación */
        scanf("%lf", &x);
        suma += x;
    }
    printf("%.2f\n", suma / n);   /* 3. Dividir e imprimir */
    return 0;
}

