#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    double x, suma = 0.0;
    for (int i = 0; i < n; i++) {
        scanf("%lf", &x);
        suma += x;
    }
    printf("%.2f\n", suma / n);
    return 0;
}
